/**
 * 大文件友好的 JSON 解析工具
 *
 * - 文件 < STREAM_THRESHOLD：直接 file.text() + JSON.parse()（快速路径）
 * - 文件 >= STREAM_THRESHOLD：使用 @streamparser/json 流式解析，逐块读取，
 *   同时通过 onProgress 回调汇报已读取字节数，避免主线程长时间无响应。
 */

import { JSONParser } from '@streamparser/json'

/** 超过此大小（字节）走流式解析 */
const STREAM_THRESHOLD = 50 * 1024 * 1024 // 50 MB

/** 每次读取的块大小 */
const CHUNK_SIZE = 4 * 1024 * 1024 // 4 MB

/**
 * 解析 JSON 文件，自动按文件大小选择策略。
 *
 * @param {File} file - 要解析的 File 对象
 * @param {(loaded: number, total: number) => void} [onProgress] - 进度回调
 * @returns {Promise<any>} 解析后的 JS 值
 */
export async function parseJsonFile(file, onProgress) {
  if (file.size < STREAM_THRESHOLD) {
    // 快速路径
    const text = await file.text()
    return JSON.parse(text)
  }

  // 流式路径
  return new Promise((resolve, reject) => {
    let result
    let loaded = 0
    const total = file.size

    const parser = new JSONParser({
      // 只取顶层值（整个文档），不做路径过滤
      paths: ['$'],
      keepStack: false,
    })

    parser.onValue = ({ value, isPartial }) => {
      // paths: ['$'] 会在顶层值完成时触发，isPartial=false 时即完整结果
      if (!isPartial) {
        result = value
      }
    }

    parser.onError = (err) => {
      reject(new Error(`流式解析失败: ${err.message}`))
    }

    parser.onEnd = () => {
      if (result !== undefined) {
        resolve(result)
      } else {
        reject(new Error('流式解析完成但未获得有效 JSON 值'))
      }
    }

    // 逐块读取并送入解析器
    ;(async () => {
      try {
        let offset = 0
        while (offset < total) {
          const end = Math.min(offset + CHUNK_SIZE, total)
          const blob = file.slice(offset, end)
          const arrayBuffer = await blob.arrayBuffer()
          const uint8 = new Uint8Array(arrayBuffer)
          parser.write(uint8)
          loaded += uint8.byteLength
          offset = end
          if (onProgress) onProgress(loaded, total)
          // 让出主线程，保持 UI 响应
          await yieldToMain()
        }
        parser.end()
      } catch (err) {
        reject(err)
      }
    })()
  })
}

/** 通过 MessageChannel 让出主线程控制权（类似 setTimeout 0 但优先级更高） */
function yieldToMain() {
  return new Promise((resolve) => {
    const { port1, port2 } = new MessageChannel()
    port1.onmessage = resolve
    port2.postMessage(null)
  })
}
